def parse_datatypes(f):
    dt = set()
    for line in f:
        if '<sect1' in line:
            break
        if '<entry><type>' not in line:
            continue
        line = re.sub('<replaceable>[^<]+</replaceable>', '', line)
        line = re.sub('<[^>]+>', '', line)
        for tmp in [t for tmp in line.split('[') for t in tmp.split(']') if '(' not in t]:
            for t in tmp.split(','):
                t = t.strip()
                if not t:
                    continue
                dt.add(' '.join(t.split()))
    dt = list(dt)
    dt.sort()
    return dt

def parse_pseudos(f):
    dt = []
    re_start = re.compile('\\s*<table id="datatype-pseudotypes-table">')
    re_entry = re.compile('\\s*<entry><type>(.+?)</type></entry>')
    re_end = re.compile('\\s*</table>')
    f = iter(f)
    for line in f:
        if re_start.match(line) is not None:
            break
    else:
        raise ValueError('pseudo datatypes table not found')
    for line in f:
        m = re_entry.match(line)
        if m is not None:
            dt.append(m.group(1))
        if re_end.match(line) is not None:
            break
    else:
        raise ValueError('end of pseudo datatypes table not found')
    if not dt:
        raise ValueError('pseudo datatypes not found')
    dt.sort()
    return dt

pygments.util.docstring_headline:
def docstring_headline(obj):
    if not obj.__doc__:
        return ''
    res = []
    for line in obj.__doc__.strip().splitlines():
        if line.strip():
            res.append(' ' + line.strip())
        else:
            break
    return ''.join(res).lstrip()

